insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_114_v1'
from (values
('127.817.d.1.A',3,'A high school student interested in machining looks up which math courses, certifications and degrees a community college machining program requires. She is determining:','["academic knowledge and skills required for postsecondary education and careers", "only her favorite foods", "only the weather", "only her vacation plans"]'::jsonb,0,'Know requirements before choosing a path.','original'),
('127.817.d.1.A',4,'A student who wants to become a CNC programmer should plan to build strong skills in:','["only cooking", "math, blueprint reading and computer applications", "only art history", "only music theory"]'::jsonb,1,'CNC careers rely on these skills.','original'),
('127.817.d.1.B',3,'A shop manager says her customers expect parts delivered on time, to print and with a friendly response to problems. These are employer expectations that help:','["reduce quality", "lower the shop''s standards", "foster positive customer satisfaction", "avoid communication"]'::jsonb,2,'Meeting expectations satisfies customers.','original'),
('127.817.d.1.B',4,'A machinist who notices a defect in a finished batch before shipping should:','["blame a coworker", "ship it anyway", "hide it", "report it so it can be corrected before the customer receives it"]'::jsonb,3,'Quality protects customers.','original'),
('127.817.d.1.C',3,'A new machinist arrives early, wears the required safety gear, follows shop procedures and treats coworkers respectfully. He is demonstrating:','["professional standards required in the workplace", "careless habits", "casual habits", "random habits"]'::jsonb,0,'Professionalism includes punctuality and respect.','original'),
('127.817.d.1.C',4,'Which habit best shows professionalism on a shop floor?','["texting while operating a machine", "arriving on time and following safety procedures", "leaving tools out", "skipping the safety meeting"]'::jsonb,1,'Reliability and safety.','original'),
('127.817.d.1.D',3,'A student writes down the certifications she wants in two years, the job she wants in five and the skills she needs to get there. She is evaluating:','["a recipe", "a game score", "personal career goals", "a sports schedule"]'::jsonb,2,'Goal setting guides planning.','original'),
('127.817.d.1.D',4,'A useful career goal is one that is:','["secret from everyone", "impossible to measure", "vague and undated", "specific and has steps and a timeline"]'::jsonb,3,'Specific goals can be tracked.','original'),
('127.817.d.1.E',3,'When the instructions for a job are unclear, a machinist asks the supervisor to restate the part number, quantity and finish before starting. She is communicating to:','["clarify objectives and expectations in the workplace", "avoid work", "slow the shop down", "confuse the supervisor"]'::jsonb,0,'Clear communication prevents errors.','original'),
('127.817.d.1.E',4,'The best time to ask a question about a job''s requirements is:','["after the part is scrapped", "before starting the work", "never", "after shipping"]'::jsonb,1,'Asking early saves material.','original'),
('127.817.d.1.F',3,'A machine shop requires safety glasses on the floor, labels hazardous chemicals and posts emergency exits. These practices show skills related to:','["office decorating", "shift changes", "health and safety in the workplace as specified by OSHA", "company advertising"]'::jsonb,2,'OSHA sets workplace safety rules.','original'),
('127.817.d.1.F',4,'OSHA is the government agency that sets and enforces rules for:','["sports leagues", "school lunches", "road maps", "workplace safety and health"]'::jsonb,3,'Occupational Safety and Health Administration.','original'),
('127.817.d.2.A',3,'A machinist writes a clear one-page procedure telling the next operator how to set up a fixture, with numbered steps and the gauge to use. She is demonstrating:','["technical writing skills for work requirements", "poetry", "story writing", "journal doodling"]'::jsonb,0,'Technical writing is clear and exact.','original'),
('127.817.d.2.A',4,'Technical writing for a machine setup sheet should be:','["very long and unclear", "clear, concise and in logical order", "random and humorous", "flowery and vague"]'::jsonb,1,'Operators must follow it exactly.','original'),
('127.817.d.2.B',3,'A machinist uses algebra to solve for the feed rate, geometry to find a bolt-circle position and trigonometry to find an angled cut. He is demonstrating:','["only counting", "only rounding", "mathematical skills such as algebra, geometry and trigonometry", "only guessing"]'::jsonb,2,'Machining uses several kinds of math.','original'),
('127.817.d.2.B',4,'A bolt circle of four holes is laid out on a plate. The angle between adjacent holes is:','["45 degrees", "120 degrees", "60 degrees", "90 degrees"]'::jsonb,3,'360 ÷ 4 = 90.','original'),
('127.817.d.2.C',3,'A machinist reads a print with feature control frames that show flatness, perpendicularity and position tolerances for each surface. She is interpreting:','["engineering drawings, including those with geometric dimensioning and tolerancing", "menu boards", "sports charts", "bus maps"]'::jsonb,0,'GD&T defines form and position tolerances.','original'),
('127.817.d.2.C',4,'On a print, a feature control frame tells the machinist:','["the delivery date", "the geometric tolerance that applies to a feature", "the shop''s address", "the part''s color"]'::jsonb,1,'It specifies form, orientation or location.','original'),
('127.817.d.2.D',3,'A student looks at a print that shows a part from the front, top and right side and then at a picture that shows all three faces in one angled view. She is describing:','["only sketches of faces", "only 2D clip art", "orthographic and isometric views of three-dimensional figures", "only photos"]'::jsonb,2,'Ortho = separate views; iso = one 3D view.','original'),
('127.817.d.2.D',4,'A single drawing that shows the top, front and right faces of a part at once is called an:','["section view", "end view", "orthographic view", "isometric view"]'::jsonb,3,'Isometric shows three faces.','original'),
('127.817.d.2.E',3,'A machinist calculates the spindle speed for a 0.500-inch end mill cutting aluminum and checks that the answer is reasonable. She is evaluating:','["mathematics as it applies to precision machining operations", "a painting", "a poem", "a song"]'::jsonb,0,'Math drives cutting parameters.','original'),
('127.817.d.2.E',4,'Spindle speed (RPM) for a cutter is found by:','["length minus width", "(cutting speed × 12) ÷ (π × cutter diameter)", "diameter plus length", "depth times feed only"]'::jsonb,1,'RPM = (CS × 3.82) / D.','original'),
('127.817.d.2.F',3,'A machinist notes that cutting with a dull tool produces more heat and needs more force because of friction. He is discussing basic concepts of physics, such as:','["only light", "only sound", "friction, force and heat as applied to machining", "only magnetism"]'::jsonb,2,'Cutting converts force into heat.','original'),
('127.817.d.2.F',4,'The heat generated while cutting metal is mostly carried away by:','["the ceiling", "the operator''s hand", "the floor", "the chips and the cutting fluid"]'::jsonb,3,'Chips remove most of the heat.','original'),
('127.817.d.3.A',3,'A student looks up a thread''s pitch diameter in the handbook, checks a catalog for a recommended insert grade and a speeds-and-feeds app for a chart. She is examining:','["resources found in recognized manufacturing reference materials", "fantasy novels", "shopping flyers", "blogs about music"]'::jsonb,0,'Reference materials provide shop data.','original'),
('127.817.d.3.A',4,'A reliable reference for the dimensions of standard threads is:','["a cookbook", "a machinist''s handbook", "a novel", "a travel guide"]'::jsonb,1,'Handbooks list thread data.','original'),
('127.817.d.3.B',3,'A machinist uses a chart to find that a 1/4-20 tap needs a #7 drill. He is demonstrating knowledge of:','["school schedules", "decorating charts", "the uses of reference charts such as tap drill charts", "weather maps"]'::jsonb,2,'Tap drill charts list drill sizes.','original'),
('127.817.d.3.B',4,'A tap drill chart tells a machinist:','["the shop''s hours", "the price of the tap", "the color of the part", "what drill size to use before tapping a thread"]'::jsonb,3,'The chart matches drill to tap.','original'),
('127.817.d.4.A',3,'A student checks that guards are in place on a lathe, ties back long hair and keeps the chuck key out of the chuck before starting. She is practicing:','["safety while running equipment commonly employed in machine shops", "horseplay", "speed-running", "shortcuts"]'::jsonb,0,'Machine shop safety habits.','original'),
('127.817.d.4.A',4,'A chuck key should never be left in the chuck because it:','["gets dirty", "can be thrown out at high speed when the spindle starts", "cools the part", "looks messy"]'::jsonb,1,'Thrown keys cause injuries.','original'),
('127.817.d.4.B',3,'A student sorts used coolant, oily rags and spent solvent into labeled containers instead of the regular trash. She is:','["ignoring waste", "mixing waste", "identifying and properly disposing of environmentally hazardous materials", "hiding waste"]'::jsonb,2,'Hazardous materials need proper disposal.','original'),
('127.817.d.4.B',4,'Used oily rags in a machine shop should be placed in:','["a plastic bag in the trash", "an open cardboard box", "a heap on the floor", "an approved, closed metal safety can"]'::jsonb,3,'They can self-ignite.','original'),
('127.817.d.4.C',3,'A class loads a G-code program into a small CNC mill, sets the work offset and runs it in single-block mode to watch each move. They are demonstrating knowledge of:','["computer numerical control (CNC) operations", "manual drilling only", "hand crank only", "hand sanding only"]'::jsonb,0,'CNC follows coded instructions.','original'),
('127.817.d.4.C',4,'Running a new CNC program in single-block mode lets the operator:','["remove the guard", "check each move before continuing", "skip the setup", "run it faster"]'::jsonb,1,'Safer first run.','original'),
('127.817.d.4.D',3,'A student reports on how 5-axis machining, automated tool changers and in-process probing may change what machinists do. She is demonstrating knowledge of:','["school clubs", "traditional crafts only", "emerging technologies that may affect the machining industry", "old tools only"]'::jsonb,2,'New technology changes jobs.','original'),
('127.817.d.4.D',4,'A probe mounted in a CNC spindle can:','["cool the part", "clean chips", "cut threads", "measure a part on the machine"]'::jsonb,3,'In-process measurement.','original'),
('127.817.d.4.E',3,'A shop heats a steel tool to a high temperature and quenches it to make it hard, then reheats it to a lower temperature to reduce brittleness. These steps are:','["hardening and tempering", "painting and sanding", "buffing and waxing", "cutting and gluing"]'::jsonb,0,'Heat treatments change hardness.','original'),
('127.817.d.4.E',4,'After hardening, steel is often tempered to:','["make it softer than before", "reduce brittleness", "change its color only", "increase brittleness"]'::jsonb,1,'Tempering relieves brittleness.','original'),
('127.817.d.4.F',3,'A student practices setting up a vise on a mill and writes up the process for a job-shadow with a local machine shop. She is applying:','["games", "painting", "technical knowledge and skills in a machine shop to career preparation", "cooking"]'::jsonb,2,'Skills are applied in a career setting.','original'),
('127.817.d.4.F',4,'A job-shadow day at a machine shop helps a student by:','["avoiding safety", "hiding the job", "replacing school", "showing real working conditions and skills employers want"]'::jsonb,3,'Real-world exposure.','original'),
('127.817.d.4.G',3,'A class sorts samples into steel, aluminum, brass and plastics such as nylon and acetal and notes how each cuts. They are identifying:','["basic metallic and non-metallic materials", "fruits", "spices", "fabrics"]'::jsonb,0,'Metals and plastics are machined.','original'),
('127.817.d.4.G',4,'Of these, a non-metallic material often machined in a shop is:','["aluminum", "nylon", "steel", "brass"]'::jsonb,1,'Nylon is a plastic.','original'),
('127.817.d.4.H',3,'A student compares the type, structure, bond and typical use of aluminum oxide and silicon carbide wheels. She is comparing:','["various papers", "various paints", "various abrasives", "various fabrics"]'::jsonb,2,'Abrasives differ in type and use.','original'),
('127.817.d.4.H',4,'An aluminum oxide wheel is generally used to grind:','["cast iron only", "glass only", "plastic only", "steel"]'::jsonb,3,'Aluminum oxide suits steel.','original'),
('127.817.d.5.A',3,'A student puts on safety glasses, secures a part in a vise and clears the bench before filing and layout. She is using:','["equipment commonly employed in bench work and layout in a safe manner", "equipment while distracted", "equipment without training", "equipment carelessly"]'::jsonb,0,'Bench work safety.','original'),
('127.817.d.5.A',4,'When using a hand file, the safe practice is to:','["push it with a bare tang", "use a handle on the tang", "use it as a hammer", "use it without a handle"]'::jsonb,1,'A tang can injure.','original'),
('127.817.d.5.B',3,'A student files a steel block flat, then files a 30-degree angle on one end and a radius on a corner to match a template. She is developing the ability to:','["weld joints", "glue pieces", "use a file to cut flats, angles and radiuses", "paint surfaces"]'::jsonb,2,'Filing shapes metal by hand.','original'),
('127.817.d.5.B',4,'To keep a file cutting well, a worker should:','["wet it", "hammer on it", "oil the teeth", "clean the teeth with a file card"]'::jsonb,3,'A file card removes pins.','original'),
('127.817.d.5.C',3,'A student coats a part with layout dye, then uses a height gage and a scriber to mark lines from a drawing onto the metal. She is employing:','["standard layout tools to transfer a part design to the actual piece", "a stapler", "a pencil only", "guesswork"]'::jsonb,0,'Layout transfers print to metal.','original'),
('127.817.d.5.C',4,'Layout dye is applied to a metal surface so that:','["it cuts faster", "scribed lines are easy to see", "it cools faster", "it gets harder"]'::jsonb,1,'Contrast makes lines visible.','original'),
('127.817.d.5.D',3,'A student marks hole locations with a center punch, then drills each hole with a handheld drill. She is performing:','["hand sanding", "hand painting", "center punching and hand drilling of holes using an electric or air drill", "hand sewing"]'::jsonb,2,'Center punching starts the drill.','original'),
('127.817.d.5.D',4,'A center punch mark is made before drilling in order to:','["make the hole bigger", "cool the drill", "remove burrs", "keep the drill from wandering"]'::jsonb,3,'The mark guides the drill.','original'),
('127.817.d.5.E',3,'A student drills a 0.201-inch hole and then turns a 1/4-20 tap a half turn forward and a quarter turn back to cut internal threads. She is performing:','["hand tapping of holes", "sanding", "painting", "welding"]'::jsonb,0,'Hand taps cut internal threads.','original'),
('127.817.d.5.E',4,'When hand tapping, turning the tap back a little after each forward turn:','["adds speed", "breaks the chip so it does not jam", "enlarges the hole", "adds heat"]'::jsonb,1,'Chip breaking prevents tap breakage.','original'),
('127.817.d.5.F',3,'A student runs a straight reamer through a drilled hole with a drill to finish it to an exact size. She is performing:','["hand sanding", "hand sawing", "hand reaming of holes using an electric or air hand drill", "hand welding"]'::jsonb,2,'Reaming finishes holes to size.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_114_v1'
from (values
('127.817.d.5.F',4,'A hole is reamed after drilling to:','["make it rougher", "change its shape to a square", "make it undersized", "improve its size and surface finish"]'::jsonb,3,'Reamers refine holes.','original'),
('127.817.d.5.G',3,'A student works from a print to lay out every hole and edge of a NIMS-style practice part and checks the layout against a gauge. She is developing:','["a detailed layout part such as the NIMS Level 1 layout project", "a quilt", "a drawing contest", "a sculpture"]'::jsonb,0,'Detailed layout practice.','original'),
('127.817.d.5.G',4,'The National Institute for Metalworking Skills (NIMS) sets:','["road laws", "industry-recognized standards and credentials for metalworking", "school lunch menus", "sports rules"]'::jsonb,1,'NIMS credentials.','original'),
('127.817.d.5.H',3,'A student completes a NIMS-style bench part by filing, drilling, reaming and tapping to the dimensions on the print. She is developing:','["a recipe", "a poem", "a detailed bench work part such as the NIMS Level 1 bench work project", "a poster"]'::jsonb,2,'Bench work project practice.','original'),
('127.817.d.5.H',4,'Before declaring a bench work part complete, the student should:','["discard the print", "paint it", "hide it", "inspect it against the print dimensions"]'::jsonb,3,'Inspect to print.','original'),
('127.817.d.5.I',3,'At the end of each class, a student sweeps chips, wipes the benches, puts tools back in their cabinet and wipes up coolant spills. She is employing:','["basic housekeeping skills in a machine shop", "slow habits", "careless habits", "random habits"]'::jsonb,0,'Housekeeping prevents hazards.','original'),
('127.817.d.5.I',4,'A clean, organized shop floor helps prevent:','["all work", "slips, trips and lost tools", "all heat", "all noise"]'::jsonb,1,'Housekeeping is safety.','original'),
('127.817.d.6.A',3,'A student wipes a micrometer''s anvil and spindle faces, zeros it and handles it without dropping it before measuring a shaft. She is using:','["tools as hammers", "tools without cleaning", "equipment commonly used in precision measurement in a safe manner", "tools carelessly"]'::jsonb,2,'Care protects accuracy.','original'),
('127.817.d.6.A',4,'A micrometer should be stored with its measuring faces:','["tightly clamped together", "left in the sun", "dropped in a drawer", "slightly apart and lightly oiled"]'::jsonb,3,'Clamped faces can be damaged.','original'),
('127.817.d.6.B',3,'A quality technician lists the features to be checked on a bracket, the tool for each, the tolerance and how many parts to sample. She is writing:','["an inspection plan", "a poem", "a game plan", "a menu"]'::jsonb,0,'An inspection plan defines what to measure.','original'),
('127.817.d.6.B',4,'An inspection plan for a machined part should list:','["the weather", "the features, tolerances and measuring tools", "the workers'' hobbies", "the lunch menu"]'::jsonb,1,'Defines how to check quality.','original'),
('127.817.d.6.C',3,'To check a hole that must be 0.500 inch plus or minus 0.001 inch, a technician picks a bore gage rather than a ruler. She is identifying and selecting:','["a random tool", "the least accurate tool", "the required measuring instruments to conduct the inspection", "no tool"]'::jsonb,2,'Match tool precision to tolerance.','original'),
('127.817.d.6.C',4,'A good rule is that a measuring instrument should be at least how many times more precise than the tolerance being checked?','["2 times", "the same", "half", "10 times"]'::jsonb,3,'The 10-to-1 rule.','original'),
('127.817.d.6.D',3,'A shop plots the diameter of every tenth part on a chart with upper and lower limits to see when the process starts drifting. She is describing:','["statistical process control", "a sports score", "a weather report", "a shopping list"]'::jsonb,0,'SPC tracks stability.','original'),
('127.817.d.6.D',4,'The purpose of statistical process control is to:','["hide errors", "detect process changes before bad parts are made", "delay production", "increase scrap"]'::jsonb,1,'Monitor trends.','original'),
('127.817.d.7.A',3,'A student uses a tool post, a tailstock and a steady rest to hold and support a long shaft in the lathe. She is using:','["garden tools", "sports gear", "accessories commonly implemented on and around a lathe in a safe manner", "kitchen tools"]'::jsonb,2,'Lathe accessories support work.','original'),
('127.817.d.7.A',4,'A steady rest is used on a lathe to:','["speed up the spindle", "cool the tool", "hold the chuck key", "support a long, slender workpiece"]'::jsonb,3,'Prevents deflection.','original'),
('127.817.d.7.B',3,'A student weighs the slower setup and the ability to center odd-shaped parts of a four-jaw chuck against the speed of a three-jaw chuck. She is analyzing:','["the advantages and disadvantages of a four-jaw independent chuck and a three-jaw chuck", "sizes of shoes", "colors", "flavors"]'::jsonb,0,'Compare chucks for each job.','original'),
('127.817.d.7.B',4,'A four-jaw independent chuck is the better choice for holding:','["only round stock quickly", "square or irregular parts that must be centered precisely", "only wood", "only paper"]'::jsonb,1,'Each jaw moves separately.','original'),
('127.817.d.7.C',3,'A student sets a dial indicator on a part in a four-jaw chuck and adjusts the jaws until the needle moves no more than 0.003 inch total. She is:','["oiling the chuck", "guessing", "indicating a part in a four-jaw independent chuck within .003 inch total indicator reading", "painting the chuck"]'::jsonb,2,'Tight TIR gives accuracy.','original'),
('127.817.d.7.C',4,'TIR on a dial indicator stands for:','["total internal radius", "tool inside reading", "time in rotation", "total indicator reading"]'::jsonb,3,'TIR measures runout.','original'),
('127.817.d.7.D',3,'A student labels the headstock, tailstock, carriage, cross slide, compound rest and spindle on a drawing of a lathe. She is identifying and describing:','["the components of a lathe", "parts of a loom", "parts of a piano", "parts of a bicycle"]'::jsonb,0,'Lathe parts have functions.','original'),
('127.817.d.7.D',4,'The part of a lathe that holds the cutting tool and moves along the bed is the:','["spindle", "carriage", "tailstock", "chuck key"]'::jsonb,1,'The carriage carries the tool.','original'),
('127.817.d.7.E',3,'A student picks a live center, a drill chuck, a boring bar and a knurling tool for different lathe jobs. She is identifying and using:','["music gear", "art supplies", "accessories and tooling for turning operations", "yard tools"]'::jsonb,2,'Turning uses many accessories.','original'),
('127.817.d.7.E',4,'A knurling tool on a lathe is used to:','["cut threads", "weld pieces", "drill holes", "press a textured pattern into a part for grip"]'::jsonb,3,'Knurls improve grip.','original'),
('127.817.d.7.F',3,'A student bores a hole to size, chamfers the edge, cuts a 1/2-13 thread and parts off the finished piece. She is demonstrating:','["standard turning operations such as boring, chamfering, cutting threads and parting", "only painting", "only sanding", "only sewing"]'::jsonb,0,'Standard lathe operations.','original'),
('127.817.d.7.F',4,'Parting on a lathe means:','["polishing a surface", "cutting a finished piece off the stock", "knurling a surface", "drilling a hole"]'::jsonb,1,'Parting separates the piece.','original'),
('127.817.d.7.G',3,'A student lists the steps, tools, speeds, feeds and depths of cut that will be used to turn a stepped shaft, in order. She is writing:','["a story", "a letter", "a detailed process plan for turning", "a speech"]'::jsonb,2,'A plan sequences operations.','original'),
('127.817.d.7.G',4,'A good process plan for turning lists the operations:','["alphabetically", "randomly", "by tool color", "in the sequence they will be performed"]'::jsonb,3,'Sequence matters.','original'),
('127.817.d.7.H',3,'A student turns a chuck-style practice part with several diameters, a thread and a groove to NIMS-style print dimensions. She is developing:','["a detailed turning part such as the NIMS Level 1 turning project", "a poster", "a poem", "a recipe"]'::jsonb,0,'Turning project practice.','original'),
('127.817.d.7.H',4,'After turning a part, a student checks that it meets the print by:','["skipping inspection", "measuring each dimension with the right gauge", "guessing", "looking at it"]'::jsonb,1,'Inspect to print.','original'),
('127.817.d.7.I',3,'After each class a student cleans the chips from the ways, wipes down the machine and puts a few drops of way oil on the slides. She is employing:','["rough use", "careless use", "basic preventative maintenance on the lathe", "slow work"]'::jsonb,2,'Maintenance extends machine life.','original'),
('127.817.d.7.I',4,'Lubricating the ways of a lathe regularly helps to:','["increase friction", "slow the spindle", "speed up rust", "reduce wear and keep movement smooth"]'::jsonb,3,'Lubrication reduces wear.','original'),
('127.817.d.8.A',3,'A student clamps a part in a vise, wears safety glasses and keeps hands away from the cutter while a mill runs. She is using:','["equipment commonly used with a milling machine in a safe manner", "horseplay", "bare hands near the cutter", "speed shortcuts"]'::jsonb,0,'Mill safety.','original'),
('127.817.d.8.A',4,'Chips from a milling machine should be cleared with:','["compressed air at people", "a brush or a chip hook, not bare hands", "a rag while the machine runs", "bare hands"]'::jsonb,1,'Chips are sharp and hot.','original'),
('127.817.d.8.B',3,'A student compares clamping a plate directly to the table, using a vise and using a fixture plate, noting the setup time and accuracy of each. She is analyzing:','["fabric choices", "food types", "the advantages and disadvantages of various work holding methods", "paint colors"]'::jsonb,2,'Each method has tradeoffs.','original'),
('127.817.d.8.B',4,'A milling vise is best for holding:','["fabric", "paper", "very large castings", "small to medium parts with parallel sides"]'::jsonb,3,'Vises grip parallel faces.','original'),
('127.817.d.8.C',3,'A student contrasts the roles of an end mill holder, a boring head, a rotary table and a dividing head. She is contrasting:','["various ancillary tools used on milling machines", "kitchen tools", "art tools", "garden tools"]'::jsonb,0,'Ancillary tools add capability.','original'),
('127.817.d.8.C',4,'A rotary table on a milling machine is used to:','["clean chips", "machine arcs and circular patterns", "measure temperature", "hold paper"]'::jsonb,1,'Rotary tables index and rotate work.','original'),
('127.817.d.8.D',3,'A student identifies the column, knee, saddle, table, quill and spindle on a diagram of a vertical mill. She is identifying:','["parts of a bicycle", "parts of a piano", "the components of a milling machine and their functions", "parts of a camera"]'::jsonb,2,'Mill components.','original'),
('127.817.d.8.D',4,'The component of a vertical mill that holds the cutter and rotates is the:','["knee", "table", "saddle", "spindle"]'::jsonb,3,'The spindle turns the tool.','original'),
('127.817.d.8.E',3,'A student uses a dial test indicator on the spindle and adjusts the head until the reading is the same at two points across the table. She is:','["tramming in the head of a vertical milling machine", "painting the mill", "guessing", "oiling the vise"]'::jsonb,0,'Tramming squares the head.','original'),
('127.817.d.8.E',4,'A mill head is trammed so that:','["the table is wet", "the spindle is square to the table", "the vise is closed", "the oil is full"]'::jsonb,1,'Tramming ensures accuracy.','original'),
('127.817.d.8.F',3,'A student sets a workpiece in a milling vise, taps it down on parallels and checks the face with a dial indicator before cutting. She is:','["painting the vise", "guessing", "locating and setting a workpiece in a milling vise using a dial indicator", "hammering the part flat"]'::jsonb,2,'Indicators verify setup.','original'),
('127.817.d.8.F',4,'A reason to indicate a part in a vise is to:','["make it dirty", "make it hot", "make it noisy", "confirm it is square and positioned correctly"]'::jsonb,3,'Indicating confirms accuracy.','original'),
('127.817.d.8.G',3,'A student mills all six faces of an aluminum block so that opposite faces are parallel and adjacent faces are square, to within a few thousandths. She is developing:','["a square block in the milling machine to close tolerances", "a triangle", "a round ball", "a ring"]'::jsonb,0,'Square block practice.','original'),
('127.817.d.8.G',4,'After milling a block square, the student checks that adjacent faces are square by using:','["a ruler only", "a machinist''s square or indicator", "a scale only", "her eyes only"]'::jsonb,1,'Check squareness with a gauge.','original'),
('127.817.d.8.H',3,'A student spot drills, drills, reams and counterbores holes in a plate at coordinates from the print. She is demonstrating:','["only sewing", "only painting", "various hole-making activities such as spot drilling, drilling, reaming and boring", "only sanding"]'::jsonb,2,'Hole-making operations.','original'),
('127.817.d.8.H',4,'A spot drill is used before a twist drill in order to:','["remove burrs", "finish a hole", "cut threads", "start an accurate hole location"]'::jsonb,3,'Spot drills prevent wander.','original'),
('127.817.d.8.I',3,'A student takes a cut with the cutter turning against the feed and then with it, and mills a slot and a pocket in an aluminum plate. She is demonstrating:','["various milling activities such as climb milling, conventional milling, slotting and pocketing", "only sewing", "only painting", "only gluing"]'::jsonb,0,'Milling strategies.','original'),
('127.817.d.8.I',4,'In climb milling, the cutter teeth rotate:','["against the feed", "with the direction of the feed", "sideways", "upward only"]'::jsonb,1,'Climb milling cuts with the feed.','original'),
('127.817.d.8.J',3,'A student writes the sequence of operations for milling a bracket, including the cutter size, speeds, feeds and depth of cut for each pass. She is writing:','["a letter", "a poem", "a detailed process plan for milling, including feeds, speeds and tooling", "a note"]'::jsonb,2,'Process plans define milling.','original'),
('127.817.d.8.J',4,'A process plan for a mill job should include the:','["worker''s age", "weather", "price of lunch", "tools, speeds, feeds and order of operations"]'::jsonb,3,'Plan the details.','original'),
('127.817.d.8.K',3,'A student mills a practice part with pockets, slots, holes and a contour to NIMS-style dimensions. She is developing:','["a detailed milling part such as the NIMS Level 1 milling part", "a poster", "a quilt", "a poem"]'::jsonb,0,'Milling project practice.','original'),
('127.817.d.8.K',4,'Before removing a milled part from the vise, a good habit is to:','["skip inspection", "check that critical features are within tolerance", "hide the part", "discard the print"]'::jsonb,1,'Check before unclamping.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_114_v1'
from (values
('127.817.d.8.L',3,'After a mill job, a student brushes the chips off the table, wipes the machine, checks the coolant level and oils the ways. She is employing:','["speed use", "careless use", "basic preventative maintenance on the milling machine", "rough use"]'::jsonb,2,'Maintenance keeps machines accurate.','original'),
('127.817.d.8.L',4,'Keeping a mill''s table and ways clean and lubricated helps to:','["hide problems", "increase friction", "speed rust", "prevent wear and keep it accurate"]'::jsonb,3,'Clean, lubricated machines last.','original'),
('127.817.d.8.E',3,'Before running a surface grinder, a student checks the wheel for cracks, stands to the side during the first start-up and wears eye protection. She is using:','["proper safety procedures for surface grinding operations", "bare hands", "no guards", "no eye protection"]'::jsonb,0,'Surface grinding safety.','original'),
('127.817.d.8.E',4,'A new grinding wheel should be started up:','["with the guard off", "with guards in place and the operator out of line with the wheel", "at double speed", "with the operator in front"]'::jsonb,1,'Ring test and safe startup.','original'),
('127.817.d.9.A',3,'A student uses a band saw, a pedestal grinder and a drill press, following the posted rules for each. She is using:','["equipment while rushed", "equipment without training", "support equipment commonly found in a machine shop in a safe manner", "equipment carelessly"]'::jsonb,2,'Support equipment safety.','original'),
('127.817.d.9.A',4,'Before using the pedestal grinder, a worker should:','["wear loose gloves", "move the rest far away", "remove the guard", "adjust the tool rest close to the wheel"]'::jsonb,3,'A narrow gap prevents jamming.','original'),
('127.817.d.9.B',3,'A student picks a grinding wheel for sharpening a drill bit, checking the grit, grade and the rated speed against the grinder''s RPM. She understands:','["basic pedestal grinder functions such as wheel selection", "sewing needles", "cooking pans", "bike pedals"]'::jsonb,0,'Wheel selection matters.','original'),
('127.817.d.9.B',4,'A grinding wheel should never be used at a speed greater than:','["its weight", "its maximum rated speed", "its color", "its price"]'::jsonb,1,'Overspeed can cause bursting.','original'),
('127.817.d.9.C',3,'A student chooses a blade with the right tooth count, sets the band saw''s speed for aluminum and adjusts the feed. She understands:','["weather", "baking times", "basic sawing functions such as band type, speed and feeds", "song speed"]'::jsonb,2,'Saw settings matter.','original'),
('127.817.d.9.C',4,'For cutting thin material on a band saw, the best blade has:','["fewer teeth per inch", "a very wide blade", "no teeth", "more teeth per inch"]'::jsonb,3,'Thin stock needs fine teeth.','original'),
('127.817.d.9.D',3,'A student clamps a part to the table, centers the drill using a center punch and selects the correct speed for the drill size and material. She understands:','["basic drill press operations, including work holding and speeds", "cooking", "sewing", "cleaning"]'::jsonb,0,'Drill press basics.','original'),
('127.817.d.9.D',4,'On a drill press, the larger the drill bit, generally:','["no coolant needed", "the slower the speed should be", "the same speed", "the faster the speed"]'::jsonb,1,'Large drills need slower speeds.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
